// Owner-scoped recovery of media already generated by the existing Queue.
import {readImageReceipt,IMAGE_RECEIPT_KEY,type ImageReceipt} from './vpsImageJob.js';
import {sanitizePersistedVideoJob,type PersistedVideoJob} from './videoStudioPersistence.js';
import {persistStudioImage,persistStudioVideo} from './studioMediaStore.js';
export type StudioRecoveryKind='image'|'video';
export type StudioRecoveryRow={job_id:string;kind:StudioRecoveryKind;receipt:unknown;status:'pending'|'archived'|'failed'|'transferred';error_code?:string|null;mime?:string|null;sha256?:string|null;byte_size?:number|null};
type Chunk={job_id:string;offset:number;size:number;sha256:string;data:string};
export type StudioRecoveryTransport={
 register:(id:string,kind:StudioRecoveryKind,receipt:ImageReceipt|PersistedVideoJob)=>Promise<string>;
 list:()=>Promise<StudioRecoveryRow[]>;
 chunk:(id:string,offset:number)=>Promise<Chunk>;
 sync:()=>Promise<void>;
 confirm:(id:string)=>Promise<string>;
};
const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const CHUNK=262144,MAX=8388608;
export function validateStudioRecoveryRow(r:StudioRecoveryRow){
 if(!r||!uuid.test(r.job_id)||!['image','video'].includes(r.kind)||!['pending','archived','failed','transferred'].includes(r.status))throw Error('STUDIO_RECOVERY_ROW_INVALID');
 if(r.kind==='image'){
  const v=readImageReceipt({getItem:k=>k===IMAGE_RECEIPT_KEY?JSON.stringify(r.receipt):null,setItem:()=>{},removeItem:()=>{}});
  if(!v||v.jobId!==r.job_id)throw Error('STUDIO_RECOVERY_RECEIPT_INVALID');
  return {kind:'image' as const,receipt:v};
 }
 const v=sanitizePersistedVideoJob(r.receipt);
 if(!v||v.autonomous!==true||v.queueId!==r.job_id||v.submissionId!==r.job_id)throw Error('STUDIO_RECOVERY_RECEIPT_INVALID');
 return {kind:'video' as const,receipt:v};
}
export async function readArchivedStudioBlob(r:StudioRecoveryRow,transport:StudioRecoveryTransport){
 validateStudioRecoveryRow(r);
 const mime=r.kind==='image'?'image/webp':'video/mp4';
 if(r.status!=='archived'||r.mime!==mime||typeof r.sha256!=='string'||!/^[a-f0-9]{64}$/.test(r.sha256)||!Number.isSafeInteger(r.byte_size)||r.byte_size!<512||r.byte_size!>MAX)throw Error('STUDIO_RECOVERY_MANIFEST_INVALID');
 const bytes=new Uint8Array(r.byte_size!);
 for(let offset=0;offset<bytes.length;offset+=CHUNK){
  const c=await transport.chunk(r.job_id,offset);
  if(!c||c.job_id!==r.job_id||c.offset!==offset||c.size!==bytes.length||c.sha256!==r.sha256||typeof c.data!=='string'||c.data.length>Math.ceil(CHUNK/3)*4||!/^[A-Za-z0-9+/]+={0,2}$/.test(c.data))throw Error('STUDIO_RECOVERY_CHUNK_INVALID');
  const raw=atob(c.data);if(btoa(raw)!==c.data||raw.length!==Math.min(CHUNK,bytes.length-offset))throw Error('STUDIO_RECOVERY_CHUNK_INVALID');
  for(let i=0;i<raw.length;i++)bytes[offset+i]=raw.charCodeAt(i);
 }
 const sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),n=>n.toString(16).padStart(2,'0')).join('');
 if(sha!==r.sha256)throw Error('STUDIO_RECOVERY_HASH_MISMATCH');
 return new Blob([bytes],{type:mime});
}
export function createStudioMediaRecovery(t:StudioRecoveryTransport){
 return {
  registerImage:async(r:ImageReceipt)=>{validateStudioRecoveryRow({job_id:r.jobId,kind:'image',receipt:r,status:'pending'});const status=await t.register(r.jobId,'image',r);if(status!=='pending')throw Error('STUDIO_RECOVERY_ALREADY_REGISTERED');},
  registerVideo:async(r:PersistedVideoJob)=>{validateStudioRecoveryRow({job_id:r.queueId,kind:'video',receipt:r,status:'pending'});const status=await t.register(r.queueId,'video',r);if(status!=='pending')throw Error('STUDIO_RECOVERY_ALREADY_REGISTERED');},
  list:async(kind:StudioRecoveryKind)=>{const rows=await t.list();if(!Array.isArray(rows)||rows.length>50)throw Error('STUDIO_RECOVERY_LIST_INVALID');for(const r of rows)validateStudioRecoveryRow(r);return rows.filter(r=>r.kind===kind);},
  read:(r:StudioRecoveryRow)=>readArchivedStudioBlob(r,t),
  transfer:async(r:StudioRecoveryRow)=>{
   const v=validateStudioRecoveryRow(r),blob=await readArchivedStudioBlob(r,t);
   const asset=v.kind==='image'?await persistStudioImage(v.receipt,blob):await persistStudioVideo(v.receipt,blob);
   // The existing Atomic V3 sync verifies private Storage bytes before commit.
   await t.sync();
   if(await t.confirm(r.job_id)!=='transferred')throw Error('STUDIO_RECOVERY_TRANSFER_PENDING');
   return asset;
  }
 };
}
